    "id": "la-compliquee",
    "title": "La Compliquée",
    "players": "3 ou 4",
    "cards": "104 (2 jeux de 52, sans les Fous)",
    "difficulty": "Facile",
    "type": "Mémoire",
    "goal": "Trouver le plus de paires parmi 104 cartes face cachée",
    "aliases": "La Compliquée",
    "playerMin": 3,
